fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    assert_eq!(a.len(), mask.len(), "mask must have same length as a");
    assert!(!values.is_empty(), "values must be non-empty");

    let n = a.len();
    let m = values.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        if mask[i] {
            result.push(values[i % m]);
        } else {
            result.push(a[i]);
        }
    }

    result
}